from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class DistNames(SchemaObject):
    config = SchemaField(name='config', optional=True)
    runtime = SchemaField(name='runtime', optional=True)

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime

        super().__init__()


class ChannelsMapping(SchemaObject):
    rmod_r_id = SchemaField(name='rmodRId', not_null=True)
    direction = SchemaField(name='direction', optional=True)
    ant_port_id = SchemaField(name='antPortId', optional=True)
    ant_port_name = SchemaField(name='antPortName', optional=True)

    def __init__(self, rmod_r_id, direction, ant_port_id, ant_port_name):
        self.rmod_r_id = rmod_r_id
        self.direction = direction
        self.ant_port_id = ant_port_id
        self.ant_port_name = ant_port_name

        super().__init__()


class CellsStatusNoBasicCellASMV1(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    name = SchemaField(name='name', not_null=True)
    nr_cell_identity = SchemaField(name='nrCellIdentity')
    physical_layer_cell_id = SchemaField(name='physicalLayerCellID', not_null=True)
    nrarfcn = SchemaField(name='nrarfcn', optional=True)
    technology = SchemaField(name='technology', not_null=True)
    nrarfcn_dl = SchemaField(name='nrarfcnDl', optional=True)
    nrarfcn_ul = SchemaField(name='nrarfcnUl', optional=True)
    cell_group_id = SchemaField(name='cellGroupId', not_null=True)
    administrative_state = SchemaField(name='administrativeState', not_null=True)
    operational_state = SchemaField(name='operationalState')
    blocking_state = SchemaField(name='blockingState', optional=True)
    dist_names = SchemaField(name='distNames', klass=DistNames, not_null=True)
    availability_status = SchemaField(name='availabilityStatus')
    procedural_status = SchemaField(name='proceduralStatus')
    band = SchemaField(name='band', not_null=True)
    p_max = SchemaField(name='pMax', not_null=True)
    dl_mimo_mode = SchemaField(name='dlMimoMode', not_null=True)
    ul_mimo_mode = SchemaField(name='ulMimoMode', not_null=True)
    ch_bw_dl = SchemaField(name='chBwDl', optional=True)
    ch_bw_ul = SchemaField(name='chBwUl', optional=True)
    ch_bw = SchemaField(name='chBw', optional=True)
    channels_mapping = SchemaField(name='channelsMapping', klass=ChannelsMapping, not_null=True, many=True)

    def __init__(self,id, name, nr_cell_identity, physical_layer_cell_id, nrarfcn, technology, nrarfcn_dl, nrarfcn_ul, cell_group_id,
                 administrative_state, operational_state, blocking_state, dist_names, availability_status, procedural_status, band, p_max,
                 dl_mimo_mode, ul_mimo_mode, ch_bw_dl, ch_bw_ul, ch_bw, channels_mapping):
        self.id = id
        self.name = name
        self.nr_cell_identity = nr_cell_identity
        self.physical_layer_cell_id = physical_layer_cell_id
        self.nrarfcn = nrarfcn
        self.technology = technology
        self.nrarfcn_dl = nrarfcn_dl
        self.nrarfcn_ul = nrarfcn_ul
        self.cell_group_id = cell_group_id
        self.administrative_state = administrative_state
        self.operational_state = operational_state
        self.blocking_state = blocking_state
        self.dist_names = dist_names
        self.availability_status = availability_status
        self.procedural_status = procedural_status
        self.band = band
        self.p_max = p_max
        self.dl_mimo_mode = dl_mimo_mode
        self.ul_mimo_mode = ul_mimo_mode
        self.ch_bw_dl = ch_bw_dl
        self.ch_bw_ul = ch_bw_ul
        self.ch_bw = ch_bw
        self.channels_mapping = channels_mapping

        super().__init__()
